/* runtime_table.js -- renders the measured-runtime table shared by the demo pages.
 *
 * Data comes from runtime_data.js (window.TSP_RUNTIME), which is generated by
 * bench/runtime_bench.js. Usage:
 *
 *   RuntimeTable.mount(el, { n: 18, rows: ['bgma-mid', 'bound', 'exact'] })
 *   RuntimeTable.update({ n: 30, rows: [...] })     // re-highlight on control changes
 *
 * `n` highlights the nearest measured size; `rows` highlights the methods the page runs.
 */
(function (global) {
  'use strict';
  var STYLE = [
    '.rt { background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:12px 14px 14px; margin-top:16px; }',
    '.rt h2 { font-size:13px; margin:0 0 4px; display:flex; justify-content:space-between; align-items:baseline; gap:10px; flex-wrap:wrap; }',
    '.rt .tabs { display:flex; gap:4px; }',
    '.rt .tabs button { font-size:11.5px; padding:3px 9px; border-radius:6px; }',
    '.rt .tabs button.on { background:var(--held); border-color:var(--held); color:#fff; }',
    '.rt .meta { color:var(--muted); font-size:11.5px; line-height:1.5; margin:2px 0 10px; }',
    '.rt .scroll { overflow-x:auto; }',
    '.rt table { border-collapse:collapse; width:100%; font-size:12.5px; min-width:560px; }',
    '.rt th, .rt td { padding:5px 10px; border-bottom:1px solid var(--line); text-align:right; white-space:nowrap; }',
    '.rt th:first-child, .rt td:first-child { text-align:left; }',
    '.rt th { font-weight:500; font-size:11.5px; letter-spacing:.02em; color:var(--muted); text-transform:none; }',
    '.rt td { font-family:var(--mono); }',
    '.rt td:first-child { font-family:var(--sans); }',
    '.rt tr.sep td { border-top:2px solid var(--line); }',
    '.rt tr.hl td:first-child { font-weight:600; color:var(--held); }',
    '.rt tr.hl td { background:color-mix(in srgb, var(--held) 7%, transparent); }',
    '.rt td.col, .rt th.col { background:color-mix(in srgb, var(--algo) 9%, transparent); }',
    '.rt td.k { color:var(--muted); }',
    '.rt .foot { color:var(--muted); font-size:11.5px; line-height:1.5; margin:10px 0 0; }'
  ].join('\n');

  function fmtMs(x) {
    if (x == null) return '—';
    if (x < 1) return Math.round(x * 1000) + ' µs';
    if (x < 1000) return (x < 10 ? x.toFixed(1) : Math.round(x)) + ' ms';
    return (x / 1000).toFixed(x < 10000 ? 2 : 1) + ' s';
  }
  function fmtGap(x) { return x == null ? '—' : (x >= 0 ? '+' : '') + x.toFixed(2) + '%'; }

  var state = { el: null, view: 'time', n: null, rows: [] };

  function nearest(ns, n) {
    var best = ns[0];
    for (var i = 0; i < ns.length; i++) if (Math.abs(ns[i] - n) < Math.abs(best - n)) best = ns[i];
    return best;
  }

  function render() {
    var el = state.el, R = global.TSP_RUNTIME;
    if (!el) return;
    if (!R) { el.innerHTML = ''; return; }
    var col = state.n == null ? null : nearest(R.ns, state.n);
    var time = state.view === 'time';
    var html = '<h2><span>Measured runtime of the algorithms</span><span class="tabs">' +
      '<button data-v="time" class="' + (time ? 'on' : '') + '">time</button>' +
      '<button data-v="gap" class="' + (time ? '' : 'on') + '">tour quality</button></span></h2>' +
      '<p class="meta">' + (time ? 'Median wall time per instance' : 'Mean excess over the best tour any method found on the same instance') +
      ' · ' + R.meta.cpu + ', Node ' + R.meta.node + ' · ' + R.meta.instancesPerCell +
      ' instances per cell (uniform + clustered) · measured ' + R.meta.date + '</p>' +
      '<div class="scroll"><table><thead><tr><th>algorithm</th>';
    R.ns.forEach(function (n) { html += '<th class="' + (n === col ? 'col' : '') + '">n = ' + n + '</th>'; });
    html += time ? '<th title="empirical exponent: time ~ n^k, from first to last n">~ n<sup>k</sup></th>' : '';
    html += '</tr></thead><tbody>';
    var sepDone = false;
    R.methods.forEach(function (m) {
      if (!time && m.ref) return;
      var cls = [];
      if (state.rows.indexOf(m.id) >= 0) cls.push('hl');
      if (m.ref && !sepDone && time) { cls.push('sep'); sepDone = true; }
      html += '<tr class="' + cls.join(' ') + '" title="' + (m.note || '') + '"><td>' + m.label + '</td>';
      R.ns.forEach(function (n) {
        var c = m.cells[n];
        html += '<td class="' + (n === col ? 'col' : '') + '">' +
          (c ? (time ? fmtMs(c.ms) : fmtGap(c.gapPct)) : '—') + '</td>';
      });
      if (time) html += '<td class="k">' + (m.exponent == null ? '—' : m.exponent.toFixed(2)) + '</td>';
      html += '</tr>';
    });
    html += '</tbody></table></div>' +
      '<p class="foot">Reference rows (1-tree bound, Held–Karp) cost time but are not heuristics. ' +
      'Live timings above the canvases are this browser run (the demo uses scaled-down effort budgets); ' +
      'this table is the full Node CLI budgets from <code>bench/runtime_bench.js</code>. ' +
      'Held–Karp is only run up to n = 20.</p>';
    el.innerHTML = html;
    var btns = el.querySelectorAll('.tabs button');
    for (var i = 0; i < btns.length; i++) {
      btns[i].onclick = function () { state.view = this.getAttribute('data-v'); render(); };
    }
  }

  function mount(el, opts) {
    if (!document.getElementById('rt-style')) {
      var s = document.createElement('style'); s.id = 'rt-style'; s.textContent = STYLE;
      document.head.appendChild(s);
    }
    el.classList.add('rt');
    state.el = el;
    update(opts || {});
  }
  function update(opts) {
    if (opts.n != null) state.n = opts.n;
    if (opts.rows) state.rows = opts.rows;
    render();
  }

  global.RuntimeTable = { mount: mount, update: update, fmtMs: fmtMs };
})(window);
